import { CardElement, useStripe, useElements } from "@stripe/react-stripe-js";
import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { ethers } from "ethers";

const API_BASE_URL = "http://localhost:5001/api/payment";

const cardStyle = {
  style: {
    base: {
      color: "#ffffff",
      fontSize: "16px",
      "::placeholder": {
        color: "#aab7c4",
      },
    },
    invalid: {
      color: "#ff0033",
    },
  },
};

const PaymentForm = () => {
  const stripe = useStripe();
  const elements = useElements();
  const navigate = useNavigate();

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);

  const [amount, setAmount] = useState("");
  const [currency, setCurrency] = useState("usd");
  const [type, setType] = useState("full");
  const [method, setMethod] = useState("stripe");
  const [clientWallet, setClientWallet] = useState(null);

  const [clientId, setClientId] = useState(null);
  const [freelancerId, setFreelancerId] = useState(null);
  const [jobId, setJobId] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      alert("Please login to access the payment page.");
      navigate("/login");
      return;
    }

    const user = JSON.parse(localStorage.getItem("user"));
    if (user && user._id) setClientId(user._id);
    else if (user && user.id) setClientId(user.id);

    const storedJobId = localStorage.getItem("jobId");
    if (storedJobId) setJobId(storedJobId);

    const storedFreelancerId = localStorage.getItem("freelancerId");
    if (storedFreelancerId) setFreelancerId(storedFreelancerId);
  }, [navigate]);

  const connectWallet = async () => {
    if (!window.ethereum) {
      setError("MetaMask is not installed. Please install it to use crypto payments.");
      return;
    }
    try {
      await window.ethereum.request({ method: "eth_requestAccounts" });
      const provider = new ethers.BrowserProvider(window.ethereum);
      const signer = await provider.getSigner();
      const address = await signer.getAddress();
      setClientWallet(address);
    } catch (err) {
      console.error("Wallet connection error", err);
      setError("Wallet connection failed.");
    }
  };

  const isValidObjectId = (id) => /^[0-9a-fA-F]{24}$/.test(id);

  const handlePayment = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setSuccess(false);

    if (!amount || isNaN(amount) || amount <= 0) {
      setError("Invalid amount provided.");
      setLoading(false);
      return;
    }

    if (!currency || typeof currency !== "string") {
      setError("Invalid currency format.");
      setLoading(false);
      return;
    }

    if (!type || !["full", "escrow"].includes(type)) {
      setError("Invalid or missing payment type.");
      setLoading(false);
      return;
    }

    if (!clientId || !freelancerId) {
      setError("Missing required IDs (client, freelancer, job). Please retry.");
      setLoading(false);
      return;
    }

    if (![clientId, freelancerId, jobId].every(isValidObjectId)) {
      setError("One or more provided IDs are invalid. Ensure they're valid ObjectIds.");
      setLoading(false);
      return;
    }

    const token = localStorage.getItem("token");
    if (!token) {
      setError("No auth token found. Please log in again.");
      setLoading(false);
      return;
    }

    const payload = {
      amount: parseFloat(amount),
      currency: currency.toLowerCase(),
      type,
      freelancerId,
      jobId,
    };

    try {
      if (method === "stripe") {
        if (!stripe || !elements) {
          setError("Stripe.js has not loaded yet.");
          setLoading(false);
          return;
        }

        const response = await axios.post(`${API_BASE_URL}/create-payment`, payload, {
          headers: { Authorization: `Bearer ${token}` },
        });

        const clientSecret = response.data.clientSecret;
        if (!clientSecret) {
          setError("No clientSecret returned from server.");
          setLoading(false);
          return;
        }

        const result = await stripe.confirmCardPayment(clientSecret, {
          payment_method: {
            card: elements.getElement(CardElement),
          },
        });

        if (result.error) {
          setError(result.error.message);
        } else if (result.paymentIntent?.status === "succeeded") {
          setSuccess(true);
        } else {
          setError("Payment did not succeed.");
        }
      } else if (method === "crypto") {
        if (!clientWallet) {
          await connectWallet();
          if (!clientWallet) {
            setError("Wallet not connected.");
            setLoading(false);
            return;
          }
        }

        const response = await axios.post(
          `${API_BASE_URL}/crypto-request`,
          {
            freelancerId,
            jobId,
            type,
            milestones: [{ title: "Single Payment", amountUSD: parseFloat(amount) }],
          },
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );

        if (!response.data?.payments?.length) {
          setError("No crypto payments returned from the server.");
          setLoading(false);
          return;
        }

        const cryptoPayment = response.data.payments[0];
        const provider = new ethers.BrowserProvider(window.ethereum);
        const signer = await provider.getSigner();
        const tx = await signer.sendTransaction({
          to: cryptoPayment.toWallet,
          value: ethers.parseEther(cryptoPayment.amountCrypto),
        });

        await axios.post(
          `${API_BASE_URL}/verify-crypto`,
          {
            intentId: cryptoPayment._id,
            txHash: tx.hash,
          },
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );
        setSuccess(true);
        setError(null);
      }
    } catch (err) {
      console.error("Payment error:", err);
      setError(err?.response?.data?.error || "Payment failed. Please try again.");
    }
    setLoading(false);
  };

  return (
    <form onSubmit={handlePayment} style={{ maxWidth: "400px", margin: "auto", background: "#222", padding: "20px", borderRadius: "8px", color: "#fff" }}>
      <label>Amount (e.g. 100)</label>
      <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} placeholder="Enter amount" style={{ width: "100%", padding: "8px", marginBottom: "10px" }} />

      <label>Currency</label>
      <input type="text" value={currency} onChange={(e) => setCurrency(e.target.value)} placeholder="e.g. usd" style={{ width: "100%", padding: "8px", marginBottom: "10px" }} />

      <label>Payment Type</label>
      <select value={type} onChange={(e) => setType(e.target.value)} style={{ width: "100%", padding: "8px", marginBottom: "10px" }}>
        <option value="full">Full Payment</option>
        <option value="escrow">Escrow</option>
      </select>

      <label>Payment Method</label>
      <select value={method} onChange={(e) => setMethod(e.target.value)} style={{ width: "100%", padding: "8px", marginBottom: "20px" }}>
        <option value="stripe">Credit/Debit Card</option>
        <option value="crypto">Cryptocurrency</option>
      </select>

      {method === "crypto" && (
        <button type="button" onClick={connectWallet} style={{ background: "#444", color: "#fff", padding: "10px", border: "1px solid #888", borderRadius: "5px", marginBottom: "10px", width: "100%" }}>
          {clientWallet ? `Connected: ${clientWallet.slice(0, 6)}...${clientWallet.slice(-4)}` : "\ud83d\udd0c Connect Wallet"}
        </button>
      )}

      {method === "stripe" && (
        <>
          <label>Card Details</label>
          <div style={{ padding: "10px", background: "#333", borderRadius: "5px", marginBottom: "15px" }}>
            <CardElement options={cardStyle} />
          </div>
        </>
      )}

      {error && <p style={{ color: "red", marginTop: "10px" }}>{error}</p>}
      {success && <p style={{ color: "green", marginTop: "10px" }}>Payment successful!</p>}

      <button type="submit" disabled={loading} style={{ marginTop: "10px", background: "purple", color: "#fff", padding: "10px", border: "none", borderRadius: "5px", width: "100%" }}>
        {loading ? "Processing..." : "Pay Now"}
      </button>
    </form>
  );
};

export default PaymentForm;
